SET @q1 = (SELECT id FROM attribute_def WHERE target = 'EQUIPMENT' AND department_id = 1 AND name = '자산 관리번호' AND kind = 'SHORT_TEXT' AND deleted_at IS NULL);
SET @q2 = (SELECT id FROM attribute_def WHERE target = 'EQUIPMENT' AND department_id = 1 AND name = '점검 주기' AND kind = 'DROPDOWN' AND deleted_at IS NULL);
UPDATE equipment x SET x.attr_values = CAST(JSON_OBJECT(CAST(@q1 AS CHAR), CONCAT('ASSET-', LPAD(x.id, 5, '0')), CAST(@q2 AS CHAR), JSON_OBJECT('option', ELT(1 + MOD(x.id, 4), 'o1', 'o2', 'o3', 'o4'))) AS CHAR)
WHERE x.department_id = 1 AND x.attr_values IS NULL AND MOD(x.id, 5) <> 4 AND @ok AND @q1 IS NOT NULL AND @q2 IS NOT NULL;

SET @q3 = (SELECT id FROM attribute_def WHERE target = 'EQUIPMENT' AND department_id = 2 AND name = '최근 점검일' AND kind = 'DATE' AND deleted_at IS NULL);
SET @q4 = (SELECT id FROM attribute_def WHERE target = 'EQUIPMENT' AND department_id = 2 AND name = '배터리 상태' AND kind = 'MULTIPLE_CHOICE' AND deleted_at IS NULL);
UPDATE equipment x SET x.attr_values = CAST(JSON_OBJECT(CAST(@q3 AS CHAR), DATE_FORMAT(@d0 - INTERVAL MOD(x.id * 7, 90) DAY, '%Y-%m-%d'), CAST(@q4 AS CHAR), CAST(IF(MOD(x.id, 4) = 3, '{"other": "예비 배터리만 있음"}', CONCAT('{"option": "o', 1 + MOD(x.id, 3), '"}')) AS JSON)) AS CHAR)
WHERE x.department_id = 2 AND x.attr_values IS NULL AND MOD(x.id, 5) <> 4 AND @ok AND @q3 IS NOT NULL AND @q4 IS NOT NULL;

SET @q5 = (SELECT id FROM attribute_def WHERE target = 'EQUIPMENT' AND department_id = 5 AND name = '최근 점검일' AND kind = 'DATE' AND deleted_at IS NULL);
SET @q6 = (SELECT id FROM attribute_def WHERE target = 'EQUIPMENT' AND department_id = 5 AND name = '부속품' AND kind = 'CHECKBOXES' AND deleted_at IS NULL);
SET @q7 = (SELECT id FROM attribute_def WHERE target = 'EQUIPMENT' AND department_id = 5 AND name = '사용 빈도' AND kind = 'LINEAR_SCALE' AND deleted_at IS NULL);
SET @q8 = (SELECT id FROM attribute_def WHERE target = 'EQUIPMENT' AND department_id = 5 AND name = '점검표' AND kind = 'MC_GRID' AND deleted_at IS NULL);
UPDATE equipment x SET x.attr_values = CAST(JSON_OBJECT(CAST(@q5 AS CHAR), DATE_FORMAT(@d0 - INTERVAL MOD(x.id * 7, 90) DAY, '%Y-%m-%d'), CAST(@q6 AS CHAR), CAST(ELT(1 + MOD(x.id, 3), '{"options": ["o1"]}', '{"options": ["o1", "o2"]}', '{"options": ["o1", "o2", "o3"]}') AS JSON), CAST(@q7 AS CHAR), 1 + MOD(x.id, 5), CAST(@q8 AS CHAR), CAST(ELT(1 + MOD(x.id, 2), '{"r1": "c1", "r2": "c1", "r3": "c1"}', '{"r1": "c1", "r2": "c2", "r3": "c1"}') AS JSON)) AS CHAR)
WHERE x.department_id = 5 AND x.attr_values IS NULL AND MOD(x.id, 5) <> 4 AND @ok AND @q5 IS NOT NULL AND @q6 IS NOT NULL AND @q7 IS NOT NULL AND @q8 IS NOT NULL;

SET @q9 = (SELECT id FROM attribute_def WHERE target = 'EQUIPMENT' AND department_id = 5 AND name = '취급 설명서' AND kind = 'FILE' AND deleted_at IS NULL);
UPDATE equipment x SET x.attr_values = CAST(JSON_SET(COALESCE(x.attr_values, '{}'), CONCAT('$."', @q9, '"'), JSON_ARRAY(100013)) AS CHAR)
WHERE x.id = 1 AND x.department_id = 5 AND @ok AND @q9 IS NOT NULL;
INSERT INTO attribute_value_file (file_id, attribute_id, target, owner_id)
SELECT 100013, @q9, 'EQUIPMENT', 1 FROM equipment x WHERE x.id = 1 AND x.department_id = 5 AND @ok AND @q9 IS NOT NULL;

SET @q10 = (SELECT id FROM attribute_def WHERE target = 'EQUIPMENT' AND department_id = 6 AND name = '점검 주기' AND kind = 'SHORT_TEXT' AND deleted_at IS NULL);
SET @q11 = (SELECT id FROM attribute_def WHERE target = 'EQUIPMENT' AND department_id = 6 AND name = '부속품' AND kind = 'CHECKBOXES' AND deleted_at IS NULL);
UPDATE equipment x SET x.attr_values = CAST(JSON_OBJECT(CAST(@q10 AS CHAR), ELT(1 + MOD(x.id, 3), '매월 첫째 주', '분기마다', '훈련 전후'), CAST(@q11 AS CHAR), CAST(ELT(1 + MOD(x.id, 2), '{"options": ["o1"]}', '{"options": ["o1", "o2"]}') AS JSON)) AS CHAR)
WHERE x.department_id = 6 AND x.attr_values IS NULL AND MOD(x.id, 5) <> 4 AND @ok AND @q10 IS NOT NULL AND @q11 IS NOT NULL;

SET @q12 = (SELECT id FROM attribute_def WHERE target = 'EQUIPMENT' AND department_id = 12 AND name = '임대 만료일' AND kind = 'DATE' AND deleted_at IS NULL);
SET @q13 = (SELECT id FROM attribute_def WHERE target = 'EQUIPMENT' AND department_id = 12 AND name = '보유 수량' AND kind = 'NUMBER' AND deleted_at IS NULL);
UPDATE equipment x SET x.attr_values = CAST(JSON_OBJECT(CAST(@q12 AS CHAR), DATE_FORMAT(@d0 + INTERVAL 30 + MOD(x.id * 11, 300) DAY, '%Y-%m-%d'), CAST(@q13 AS CHAR), CAST(1 + MOD(x.id, 9) AS CHAR)) AS CHAR)
WHERE x.department_id = 12 AND x.attr_values IS NULL AND MOD(x.id, 5) <> 4 AND @ok AND @q12 IS NOT NULL AND @q13 IS NOT NULL;

SET @q14 = (SELECT id FROM attribute_def WHERE target = 'PERSONNEL' AND department_id = 1 AND name = '특기' AND kind = 'SHORT_TEXT' AND deleted_at IS NULL);
UPDATE personnel x SET x.attr_values = CAST(JSON_OBJECT(CAST(@q14 AS CHAR), ELT(1 + MOD(x.id, 3), '전산 장비 정비', '무선 통신 운용', '행정 문서 관리')) AS CHAR)
WHERE x.department_id = 1 AND x.attr_values IS NULL AND @ok AND @q14 IS NOT NULL;

SET @q15 = (SELECT id FROM attribute_def WHERE target = 'PERSONNEL' AND department_id = 5 AND name = '전입일' AND kind = 'DATE' AND deleted_at IS NULL);
SET @q16 = (SELECT id FROM attribute_def WHERE target = 'PERSONNEL' AND department_id = 5 AND name = '자격증' AND kind = 'CHECKBOXES' AND deleted_at IS NULL);
UPDATE personnel x SET x.attr_values = CAST(JSON_OBJECT(CAST(@q15 AS CHAR), DATE_FORMAT(@d0 - INTERVAL 60 + MOD(x.id * 37, 600) DAY, '%Y-%m-%d'), CAST(@q16 AS CHAR), CAST(ELT(1 + MOD(x.id, 3), '{"options": ["o1"]}', '{"options": ["o2", "o3"]}', '{"options": ["o1"], "other": "정보보안기사"}') AS JSON)) AS CHAR)
WHERE x.department_id = 5 AND x.attr_values IS NULL AND @ok AND @q15 IS NOT NULL AND @q16 IS NOT NULL;

SET @q17 = (SELECT id FROM attribute_def WHERE target = 'PERSONNEL' AND department_id = 6 AND name = '전입일' AND kind = 'DATE' AND deleted_at IS NULL);
SET @q18 = (SELECT id FROM attribute_def WHERE target = 'PERSONNEL' AND department_id = 6 AND name = '비상 연락 순번' AND kind = 'NUMBER' AND deleted_at IS NULL);
UPDATE personnel x SET x.attr_values = CAST(JSON_OBJECT(CAST(@q17 AS CHAR), DATE_FORMAT(@d0 - INTERVAL 60 + MOD(x.id * 37, 600) DAY, '%Y-%m-%d'), CAST(@q18 AS CHAR), CAST(1 + MOD(x.id, 20) AS CHAR)) AS CHAR)
WHERE x.department_id = 6 AND x.attr_values IS NULL AND @ok AND @q17 IS NOT NULL AND @q18 IS NOT NULL;

SET @q19 = (SELECT id FROM attribute_def WHERE target = 'PERSONNEL' AND department_id = 7 AND name = '운전 가능 차량' AND kind = 'DROPDOWN' AND deleted_at IS NULL);
UPDATE personnel x SET x.attr_values = CAST(JSON_OBJECT(CAST(@q19 AS CHAR), JSON_OBJECT('option', ELT(1 + MOD(x.id, 3), 'o1', 'o2', 'o3'))) AS CHAR)
WHERE x.department_id = 7 AND x.attr_values IS NULL AND @ok AND @q19 IS NOT NULL;

SELECT @ok AS demo_applied, (SELECT COUNT(*) FROM work_request WHERE id >= 100001) AS requests, (SELECT COUNT(*) FROM work_item WHERE id >= 100001) AS items,
    (SELECT COUNT(*) FROM approval_doc WHERE id >= 100001) AS docs, (SELECT COUNT(*) FROM approval_doc WHERE id >= 100001 AND doc_type = 'COMPLETE') AS complete_docs,
    (SELECT COUNT(*) FROM plan_slot WHERE id >= 100001) AS plan_slots, (SELECT COUNT(*) FROM notification WHERE id >= 100001 AND read_at IS NULL) AS unread_notifications,
    (SELECT COUNT(*) FROM stored_file WHERE id >= 100001) AS files, (SELECT COUNT(*) FROM equipment WHERE attr_values IS NOT NULL) AS equipment_with_attributes;